.card {
  width: 300px;
  padding: 20px;
  border: 2px solid #ccc;
}
/* no box-sizing rule anywhere in the stylesheet */

/* <head> has no <meta name="viewport"> tag */

.sidebar { width: 300px; }

@media (max-width: 600px) {
  .sidebar { display: none; }
}

.wrapper {
  /* no height set; contains 400px of content */
}
.panel {
  height: 50%;
}

<div class="wrapper">
  <div class="panel">...</div>
  <p>... 400px of text ...</p>
</div>
